import { afterAll, beforeAll, describe, expect, test } from "bun:test";
import { chmodSync, mkdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { recordedInvocations } from "../src/execute";
import { createFixture, wardLauncher, type Fixture } from "../src/fixture";
import { writeRecordingWrapper } from "../src/live";
import { cleanupOwnedProcesses, run, SYSTEM_PATH } from "../src/process";

// Executes the hooks.json and wrapper generated by the real `ward integrate windsurf
// --guard-approved-specs` against the Cascade hooks reference (docs.devin.ai/desktop/cascade/hooks):
// - The workspace file holds {hooks: event -> [{command, powershell?, show_output?,
//   working_directory?}]}; commands run through `bash -c` from the workspace root.
// - Every event sends {agent_action_name, trajectory_id, execution_id, timestamp, model_name,
//   tool_info}; code events carry tool_info.file_path, command events tool_info.command_line and cwd.
// - Only pre-hooks block, with exit code 2, and the agent sees stderr. Post-hook output reaches only
//   the Cascade UI, when show_output is true; no hook continues the conversation.
// Windsurf is an editor, so live runs are a witnessed procedure; this suite covers the generated files.

const EVENTS = [
  "pre_read_code",
  "post_read_code",
  "pre_write_code",
  "post_write_code",
  "pre_run_command",
  "post_run_command",
  "pre_mcp_tool_use",
  "post_mcp_tool_use",
  "pre_user_prompt",
  "post_cascade_response",
  "post_cascade_response_with_transcript",
  "post_setup_worktree",
];

/** Applies the documented hooks.json shape; returns what Cascade could not run. */
function cascadeRejects(json: string): string[] {
  let config: any;
  try {
    config = JSON.parse(json);
  } catch {
    return ["not JSON"];
  }
  const errors: string[] = [];
  for (const [event, hooks] of Object.entries(config.hooks ?? {})) {
    if (!EVENTS.includes(event)) errors.push(`unknown event ${event}`);
    (hooks as any[]).forEach((hook, index) => {
      if (typeof hook.command !== "string" && typeof hook.powershell !== "string") errors.push(`${event}[${index}] has no command`);
      if (hook.show_output !== undefined && typeof hook.show_output !== "boolean") errors.push(`${event}[${index}] show_output`);
    });
  }
  return errors;
}

let fixture: Fixture;
let unguarded: Fixture;
let config: any;
let log: string;
let bin: string;

beforeAll(async () => {
  const ward = wardLauncher(process.env)!;
  fixture = await createFixture({ harness: "windsurf", guard: true, ward });
  unguarded = await createFixture({ harness: "windsurf", guard: false, ward });
  config = JSON.parse(readFileSync(join(fixture.root, ".windsurf/hooks.json"), "utf8"));
  bin = join(dirname(fixture.root), "ward-bin");
  log = join(dirname(fixture.root), "ward-log");
  writeRecordingWrapper(bin, log, ward);
  mkdirSync(join(fixture.root, "openspec/specs/auth"), { recursive: true });
  writeFileSync(join(fixture.root, "openspec/specs/auth/spec.md"), "# Auth\n");
  mkdirSync(join(fixture.root, "openspec/changes/add-x"), { recursive: true });
  writeFileSync(join(fixture.root, "openspec/changes/add-x/tasks.md"), "- [ ] 1.1\n");
  writeFileSync(join(fixture.root, "openspec-stub.sh"), "#!/bin/sh\nexit 0\n");
  chmodSync(join(fixture.root, "openspec-stub.sh"), 0o755);
});

afterAll(() => {
  fixture?.cleanup();
  unguarded?.cleanup();
  cleanupOwnedProcesses();
});

/** Runs a hook like Cascade: `bash -c` from the workspace root, event on stdin. */
async function launch(f: Fixture, event: string, toolInfo: unknown, cfg = config) {
  const before = recordedInvocations(log).length;
  const env = { ...f.env, PATH: `${bin}:${SYSTEM_PATH}` };
  const stdin =
    typeof toolInfo === "string"
      ? toolInfo
      : JSON.stringify({ agent_action_name: event, trajectory_id: "t", execution_id: "e", timestamp: "2026-10-16T00:00:00Z", model_name: "m", tool_info: toolInfo });
  const result = await run(["/bin/bash", "-c", cfg.hooks[event][0].command], { cwd: f.root, env, stdin, timeoutMs: 60_000 });
  return { result, invocations: recordedInvocations(log).slice(before) };
}

describe("generated hooks.json against the Cascade hooks reference", () => {
  test("Cascade can run every generated hook", () => {
    expect(cascadeRejects(readFileSync(join(fixture.root, ".windsurf/hooks.json"), "utf8"))).toEqual([]);
  });

  test("the guard runs before writes and commands; the check runs after writes and is shown to the user", () => {
    expect(Object.keys(config.hooks).sort()).toEqual(["post_write_code", "pre_run_command", "pre_write_code"]);
    expect(config.hooks.post_write_code[0].show_output).toBe(true);
  });

  test("negative control: the legacy configuration registers no pre-hook, so nothing could be refused", () => {
    const legacy = JSON.parse(readFileSync(join(import.meta.dir, "legacy-hooks.json.txt"), "utf8"));
    expect(Object.keys(legacy.hooks).filter((event) => event.startsWith("pre_"))).toEqual([]);
  });

  test("the ownership marker is a shell comment in each command", () => {
    for (const hooks of Object.values(config.hooks) as any[][]) {
      for (const h of hooks) expect(h.command).toEndWith("# ward-owned: windsurf-native-hooks v1");
    }
  });
});

describe("hook execution", () => {
  test("the guard blocks a write to an approved spec with exit 2 and the reason on stderr", async () => {
    const { result, invocations } = await launch(fixture, "pre_write_code", {
      file_path: join(fixture.root, "openspec/specs/auth/spec.md"),
      edits: [{ old_string: "# Auth", new_string: "# X" }],
    });
    expect(invocations.map((i) => i.argv)).toEqual([["hook", "native", "--agent", "windsurf", "--guard-approved-specs", "--event-stdin"]]);
    expect(result.exitCode).toBe(2);
    expect(result.stderr).toContain("openspec/specs/auth/spec.md");
  });

  test("the guard allows a write in an active change", async () => {
    const { result } = await launch(fixture, "pre_write_code", { file_path: join(fixture.root, "openspec/changes/add-x/tasks.md"), edits: [] });
    // Exit 0 lets the write proceed; stderr carries only Ward's diagnostics.
    expect(result.exitCode).toBe(0);
  });

  test("the guard blocks a protected command in its cwd and passes a harmless one", async () => {
    const denied = await launch(fixture, "pre_run_command", { command_line: "rm spec.md", cwd: join(fixture.root, "openspec/specs/auth") });
    expect(denied.result.exitCode).toBe(2);
    const allowed = await launch(fixture, "pre_run_command", { command_line: "ls", cwd: fixture.root });
    expect(allowed.result.exitCode).toBe(0);
  });

  test("uninspectable input is blocked", async () => {
    const { result } = await launch(fixture, "pre_run_command", "{not json");
    expect(result.exitCode).toBe(2);
  });

  test("a failing check after a write is reported on stderr for the Cascade UI", async () => {
    writeFileSync(join(fixture.root, "FAIL"), "");
    try {
      const { result, invocations } = await launch(fixture, "post_write_code", { file_path: join(fixture.root, "src/A.java"), edits: [] });
      expect(invocations.map((i) => i.argv)).toEqual([["hook", "native", "--agent", "windsurf", "--event-stdin"]]);
      expect(result.exitCode).toBe(2);
      expect(result.stderr).toContain("Ward quality findings");
    } finally {
      rmSync(join(fixture.root, "FAIL"), { force: true });
    }
  });

  test("with the guard disabled, the pre phase allows without running Ward", async () => {
    const unguardedConfig = JSON.parse(readFileSync(join(unguarded.root, ".windsurf/hooks.json"), "utf8"));
    const { result, invocations } = await launch(
      unguarded,
      "pre_run_command",
      { command_line: "rm openspec/specs/auth/spec.md", cwd: unguarded.root },
      unguardedConfig,
    );
    expect([result.exitCode, invocations.length]).toEqual([0, 0]);
  });
});
